/* course15.js — Course 15 content (Build your first company network; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 15 — Build your first company network (a consolidation/application course
   after the basics 1–5). A small company: employees, servers (web, files),
   guests, an internet connection. Step by step: brief and plan → segmentation into
   VLANs → router and addresses → firewall and zones → test and hardening. The scene
   grows with the lessons (NET → firewall → router → VLANs → guests/servers).
   Scene c15Net: NET — FW — R — {PC (employees) / HOST (guests) /
   WEB + FILE (servers)}.
   ============================================================ */
var C15R={net:[66,108],fw:[178,108],rtr:[300,108],emp:[440,48],web:[560,68],guest:[440,164],files:[560,148]};
function c15Net(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 216" width="100%" style="display:block">'
    +'<line x1="82" y1="108" x2="164" y2="108" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="192" y1="108" x2="286" y2="108" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="314" y1="102" x2="426" y2="54" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="314" y1="104" x2="546" y2="72" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="314" y1="114" x2="426" y2="158" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="314" y1="112" x2="546" y2="144" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(66,108,'globe','--cyan','NET')
    +csDev(178,108,'firewall','FW')
    +csDev(300,108,'router','R')
    +csHost(440,48,'users','--blue','PC')
    +csHost(560,68,'server','--green','WEB')
    +csHost(440,164,'laptop','--amber','HOST')
    +csHost(560,148,'nas','--green','FILE')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c15P(pfx,intro,terms){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'+intro+'</p>'
    +'<div class="osi-stage">'+c15Net(pfx)+'</div><div class="m1-cap" id="'+pfx+'cap"></div>'
    +courseStepControls(pfx)+abbrBox(terms);
}
function c15Mount(pfx,STEPS){
  function show(i){var g=$(pfx+'glow');if(g)g.innerHTML=STEPS[i].glow||'';var d=$(pfx+'dyn');if(d)d.innerHTML=STEPS[i].dyn||'';var c=$(pfx+'cap');if(c)c.innerHTML='<span>'+STEPS[i].cap+'</span>';}
  courseStepper(pfx,STEPS.length,show);
}
function c15g(name,color){var p=C15R[name];return csGlow(p[0],p[1],color,20);}
function c15lbl(x,y,tx,c){return '<text x="'+x+'" y="'+y+'" text-anchor="middle" style="font:700 7.5px var(--mono);fill:var('+c+')">'+esc(tx)+'</text>';}
function c15box(x,y,w,h,c){return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="6" style="fill:none;stroke:var('+c+');stroke-width:1.4;stroke-dasharray:4 4"/>';}
function c15pkt(path,color,dur){return '<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var('+color+')"><animateMotion path="'+path+'" dur="'+(dur||'1.4s')+'" repeatCount="indefinite"/></rect>';}

/* ============ L1 — Brief and plan ============ */
/* ---------- L1M1 — A small company: what it has and what it needs ---------- */
function renderC15Brief(){return c15P('rna',
  'Welcome to the course where you finally <b>put together</b> everything from the courses from <i>Why networks exist and how data travels</i> to <i>Network security</i>. No new magic – you will just try, on one small company network, how segments, VLANs, addresses and the firewall fit together. Picture a customer: a small company, a few dozen people. What is in it? <b>Employees</b> at computers who need the internet and shared files. <b>Servers</b>: a web server that outsiders also look at, and a file server with internal data. And now and then <b>visitors and guests</b> you want to give Wi-Fi to the internet – but certainly not into company data. All of it hangs on one <b>internet connection</b> from the provider. The scene shows that network schematically: the internet (NET) on the left, a firewall (FW) and a router (R) behind it, and on the right three groups of devices – employees (PC), servers (WEB and FILE) and guests (HOST). For now it is just a picture. Over five lessons you will <b>build it step by step</b>: first separate the groups, then give them addresses, let them out and finally protect them with rules. The single goal of the course: to turn a company’s requirements into a <b>working and secure topology</b> – and to understand every decision.',
  [['company network','one organization’s network: employees, servers and guests on a shared internet connection.'],['topology','the layout of devices and links – who is connected to whom and where data flows.']]);}
function mountC15Brief(){c15Mount('rna',[
  {glow:c15g('emp','--blue')+c15g('rtr','--blue')+c15g('fw','--blue')+c15g('net','--blue'),dyn:c15pkt('M 426 54 L 314 102 L 192 108 L 82 108','--blue','2.2s')+c15lbl(440,118,'employees: out and to shared files','--blue'),cap:'<b>Employees</b> at computers need the internet and shared files. That is the largest group of people in the company.'},
  {glow:c15g('net','--green')+c15g('fw','--green')+c15g('rtr','--green')+c15g('web','--green')+c15g('files','--green'),dyn:c15pkt('M 82 108 L 286 108 L 546 72','--green','2.2s')+c15lbl(560,116,'servers: web (also outside) and files (internal)','--green'),cap:'<b>Servers</b>: a web server that outsiders look at too, and a file server with the company’s internal data.'},
  {glow:c15g('guest','--amber')+c15g('rtr','--amber')+c15g('fw','--amber')+c15g('net','--amber'),dyn:c15pkt('M 426 158 L 314 114 L 192 108 L 82 108','--amber','2.2s')+c15lbl(440,116,'guests: only Wi-Fi to the internet, not into data','--amber'),cap:'<b>Guests and visitors</b> want Wi-Fi to the internet – but certainly not into company data. You will keep this group apart.'},
  {glow:c15g('net','--cyan')+c15g('fw','--cyan')+c15g('rtr','--cyan'),dyn:'<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var(--blue)"><animateMotion path="M 286 108 L 82 108" dur="1.8s" repeatCount="indefinite"/></rect><rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var(--green)"><animateMotion path="M 286 108 L 82 108" dur="1.8s" begin="0.6s" repeatCount="indefinite"/></rect><rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var(--amber)"><animateMotion path="M 286 108 L 82 108" dur="1.8s" begin="1.2s" repeatCount="indefinite"/></rect>'+c15lbl(180,211,'one internet connection for the whole company','--cyan'),cap:'All of it hangs on one <b>internet connection</b> through a firewall and router. Over the course you will build this network step by step.'}
]);}
/* ---------- L1M2 — Three groups, three risks ---------- */
function renderC15Groups(){return c15P('rnb',
  'Before you wire anything, ask the question every network designer asks: <b>who actually needs to talk to whom – and who does not?</b> The company has three worlds with completely different needs. <b>Employees</b> are trusted, but there are many of them and their computers catch emails, attachments and downloads – malware included. <b>Servers</b> are the most valuable: the web must be reachable from outside too (so it is the most exposed to attack), while files must <b>never</b> leave. And <b>guests</b> are entirely unknown devices you have no control over – possibly an infected laptop. If you threw everyone onto one flat network (as the course <i>Switching and VLANs</i> warns), this happens: an infected guest laptop sees straight to the file server, an employee virus spreads to the servers, and one incident floods the whole company. That flooding is called the <b>blast radius</b>. The whole design you are about to build is really about one thing: <b>shrinking the blast radius</b> by separating groups of different trust and putting a controlled door between them. Remember this threefold split by <b>trust level</b> – it is the guiding thread of the whole course.',
  [['trust level','how much you trust a device: server > employee > guest; you separate groups by this.'],['blast radius','the reach of damage – how far one incident (infection, attack) spreads before something stops it.']]);}
function mountC15Groups(){c15Mount('rnb',[
  {glow:c15g('emp','--blue')+c15g('web','--green')+c15g('files','--green')+c15g('guest','--amber'),dyn:c15lbl(430,108,'three worlds, three trust levels','--blue'),cap:'Three groups with different needs: <b>employees</b> (trusted but vulnerable), <b>servers</b> (most valuable) and <b>guests</b> (unknown).'},
  {glow:c15g('guest','--red'),dyn:c15lbl(440,116,'an infected guest on one flat network ⚠','--red'),cap:'If everyone were on one flat network, an infected guest laptop would see straight to the file server. You don’t want that.'},
  {glow:c15g('guest','--red')+c15g('rtr','--red')+c15g('files','--red')+c15g('web','--red')+c15g('emp','--red'),dyn:c15pkt('M 440 164 L 300 108 L 560 148','--red')+c15lbl(300,211,'one incident floods the whole company = large blast radius','--red'),cap:'The incident floods the whole company – that reach of damage is the <b>blast radius</b>. A flat network makes it needlessly large.'},
  {glow:c15g('emp','--green')+c15g('web','--green')+c15g('files','--green')+c15g('guest','--green'),dyn:c15lbl(430,108,'goal: separate groups → shrink the blast radius','--green'),cap:'The design goal: separate groups by <b>trust level</b> and put a controlled door between them – shrinking the blast radius.'}
]);}
/* ---------- L1M3 — Sketch the plan: groups → segments ---------- */
function renderC15Plan(){return c15P('rnc',
  'A good network is born <b>on paper before it is in cables</b>. Before you touch the simulator, sketch a plan – a ‘group → segment → what it may do’ table. You have three groups; you turn them into <b>three separate segments</b>. <b>Employees</b> → their own segment; may reach the internet and shared files, may not reach server management. <b>Servers</b> → their own segment, watched extra closely because the web is exposed outward; files stay purely inside. <b>Guests</b> → an isolated segment; may reach <b>only</b> the internet, nowhere into the company. That is the whole plan – three segments and a few arrows between them. Notice the design goes top-down: <b>first decide WHAT you want</b> (who may talk to whom), only then work out WITH WHAT you do it (VLAN, router, firewall). That order guides the whole course and matches the lessons: you build the segments with <b>VLANs</b> (lesson 2), addresses and passage between them come from the <b>router</b> (lesson 3), the controlled door and outward protection are added by the <b>firewall</b> (lesson 4), and finally you <b>test</b> it all (lesson 5). Now you have the map. Let us build by it.',
  [['network plan','a group → segment → what-it-may table; the design on paper before you touch a device.'],['top-down','first decide WHAT you want (who may talk to whom), then WITH WHAT you do it (VLAN, router, firewall).']]);}
function mountC15Plan(){c15Mount('rnc',[
  {glow:c15g('emp','--blue'),dyn:c15box(404,16,72,64,'--blue')+c15lbl(440,118,'segment 1: employees → out + files','--blue'),cap:'Plan, row one: <b>employees</b> get their own segment. May reach the internet and shared files, not server management.'},
  {glow:c15g('web','--green')+c15g('files','--green'),dyn:c15box(404,16,72,64,'--blue')+c15box(524,36,72,136,'--green')+c15lbl(560,116,'segment 2: servers → web out, files inside','--green'),cap:'Row two: <b>servers</b> get their own, extra-watched segment. The web is exposed outward, the file server stays purely inside.'},
  {glow:c15g('guest','--amber'),dyn:c15box(404,16,72,64,'--blue')+c15box(524,36,72,136,'--green')+c15box(404,132,72,64,'--amber')+c15lbl(440,116,'segment 3: guests → internet only','--amber'),cap:'Row three: <b>guests</b> get an isolated segment. May reach only the internet, nowhere into the company.'},
  {glow:c15g('net','--cyan')+c15g('fw','--cyan')+c15g('rtr','--cyan')+c15g('emp','--cyan')+c15g('web','--cyan')+c15g('files','--cyan')+c15g('guest','--cyan'),dyn:c15box(404,16,72,64,'--blue')+c15box(524,36,72,136,'--green')+c15box(404,132,72,64,'--amber')+c15pkt('M 426 54 L 314 102 L 192 108 L 82 108','--cyan','2.2s')+c15lbl(180,211,'WHAT I want → WITH WHAT: VLAN → router → firewall → test','--cyan'),cap:'You have a three-segment plan. You will build it in this order: VLANs (l. 2), router and addresses (l. 3), firewall (l. 4), test (l. 5).'}
]);}

/* ============ L2 — Segmentation into VLANs ============ */
/* ---------- L2M1 — Why one flat network is not enough ---------- */
function renderC15Flat(){return c15P('rnd',
  'We start building – and the first decision is the most important: <b>divide</b>. The simplest network is ‘everyone on one switch’, a so-called <b>flat network</b>: one big space where everyone can see everyone. It works – but it carries three problems you know from the course <i>Switching and VLANs</i>. <b>Security</b>: anyone sees anyone, so an infected guest or an employee virus reaches straight to the servers (last lesson’s large blast radius). <b>Broadcast</b>: some messages are sent to <b>everyone</b> at once on one network; the more devices, the more useless noise that burdens every computer. <b>Unmanageability</b>: in one bag you cannot say ‘this group may go there, that one may not’. You can fix it physically – buy each group its own switch and its own cabling – but that is expensive and rigid (a new guest arrives and you pull cables). You need to <b>split one physical network into several separate ones without touching the cables</b>. That is exactly what a VLAN does, which we look at in the next module. Remember: a flat network is not ‘simpler’ – it is just a <b>postponed problem</b> that blows up at your first security incident.',
  [['flat network','everyone on one network sees everyone; it carries security, broadcast and manageability risks.'],['broadcast','a message sent to everyone on the network at once; in a large flat network it makes needless noise.']]);}
function mountC15Flat(){c15Mount('rnd',[
  {glow:c15g('emp','--amber')+c15g('web','--amber')+c15g('files','--amber')+c15g('guest','--amber'),dyn:c15lbl(430,108,'flat network: everyone sees everyone','--amber'),cap:'A flat network = everyone on one switch, each sees each. It looks simple but carries three problems.'},
  {glow:c15g('guest','--red')+c15g('rtr','--red')+c15g('files','--red'),dyn:c15pkt('M 440 164 L 300 108 L 560 148','--red')+c15lbl(300,211,'problem 1: a guest reaches the files directly ⚠','--red'),cap:'<b>Security</b>: an infected guest reaches straight to the file server. A large blast radius, exactly as lesson 1 warned.'},
  {glow:c15g('emp','--violet')+c15g('web','--violet')+c15g('files','--violet')+c15g('guest','--violet'),dyn:c15lbl(430,108,'problem 2: broadcast burdens everyone','--violet'),cap:'<b>Broadcast</b>: messages for everyone are sent to each at once on one network – the more devices, the more noise.'},
  {glow:c15g('emp','--green')+c15g('guest','--green')+c15g('web','--green')+c15g('files','--green'),dyn:c15lbl(430,108,'fix: divide without pulling cables → VLAN','--green'),cap:'You need to <b>split one physical network into several without pulling cables</b>. A VLAN does that – in the next module.'}
]);}
/* ---------- L2M2 — Split into VLANs: employees, servers, guests ---------- */
function renderC15Vlans(){return c15P('rne',
  'Here is the tool from the course <i>Switching and VLANs</i>: the <b>VLAN</b> (virtual LAN). It splits one physical switch into <b>several separate networks</b>, as if you raised invisible walls. Devices in one VLAN see each other; into another VLAN they <b>cannot reach</b> on their own – broadcast does not spill out of it and a security boundary appears without a single new cable. Following the plan from lesson 1 you make three VLANs: <b>VLAN 10 employees</b>, <b>VLAN 20 servers</b>, <b>VLAN 30 guests</b>. The number (VLAN ID) is just the group’s tag: the switch tracks it for each frame itself and really inserts it into the frame (the 802.1Q tag) only on a <b>trunk</b> – out of an access port the frame goes untagged, as you saw in the Switching and VLANs course; the port you plug the guest cable or AP into you set as an <b>access port in VLAN 30</b> and that is it. What have you just gained? <b>Isolation</b>: a guest in VLAN 30 now physically has no way to ‘peek’ into VLAN 20 with the servers – that wall is simply there. And beware an important detail you will appreciate only in the next lesson: <b>a VLAN separates groups so perfectly that even those that SHOULD talk cannot do so on their own</b>. Employees cannot even reach the shared files this way. That is not a bug – it is exactly the wall. Who may cross it, and how, in a controlled way, we solve with the router in lesson 3. But first try the VLAN split in the simulator.',
  [['VLAN','virtual LAN: splits one physical switch into several separate networks without new cables.'],['VLAN ID','the group’s numeric tag (10 employees, 20 servers, 30 guests) the switch attaches to a frame.'],['isolation','a device in one VLAN cannot reach another on its own – neither broadcast nor an attack spills out.']]);}
function mountC15Vlans(){c15Mount('rne',[
  {glow:c15g('emp','--blue'),dyn:c15box(404,16,72,64,'--blue')+c15lbl(440,10,'VLAN 10','--blue')+c15lbl(440,118,'VLAN 10: employees','--blue'),cap:'<b>VLAN 10 – employees</b>. The port with their computers you set as an access port in VLAN 10. The first separate network appears.'},
  {glow:c15g('web','--green')+c15g('files','--green'),dyn:c15box(404,16,72,64,'--blue')+c15box(524,36,72,136,'--green')+c15lbl(440,10,'VLAN 10','--blue')+c15lbl(560,28,'VLAN 20','--green')+c15lbl(560,116,'VLAN 20: servers','--green'),cap:'<b>VLAN 20 – servers</b>. The web and file server go into their own VLAN, separated from users.'},
  {glow:c15g('guest','--amber'),dyn:c15box(404,16,72,64,'--blue')+c15box(524,36,72,136,'--green')+c15box(404,132,72,64,'--amber')+c15lbl(440,10,'VLAN 10','--blue')+c15lbl(560,28,'VLAN 20','--green')+c15lbl(378,168,'VLAN 30','--amber')+c15lbl(440,116,'VLAN 30: guests','--amber'),cap:'<b>VLAN 30 – guests</b>. Visitor Wi-Fi goes into an isolated VLAN. The number (VLAN ID) is the group’s tag; it is inserted into the frame (the 802.1Q tag) only on a trunk.'},
  {glow:c15g('guest','--red')+c15g('files','--red'),dyn:c15box(404,16,72,64,'--blue')+c15box(524,36,72,136,'--green')+c15box(404,132,72,64,'--amber')+c15lbl(440,10,'VLAN 10','--blue')+c15lbl(560,28,'VLAN 20','--green')+c15lbl(378,168,'VLAN 30','--amber')+c15lbl(505,120,'VLAN 30 ✕ VLAN 20','--red')+c15lbl(300,211,'the VLAN wall: a guest can’t reach the servers ✓ (nor employees the files)','--red'),cap:'<b>Isolation</b> done: a guest in VLAN 30 can’t peek into VLAN 20. The wall is so perfect that even those that should can’t talk on their own – the router fixes that (lesson 3).'}
]);}
/* ---------- L2M3 — Guest isolation ---------- */
function renderC15GuestVlan(){return c15P('rnf',
  'Let us pause at the most sensitive group – the <b>guests</b> – because they reveal whether you truly grasp segmentation. From the company’s view a guest laptop is a <b>completely foreign device</b>: you do not know who manages it, whether it is up to date, whether it is infected. The rule was: a guest may reach <b>only the internet</b>, nowhere into the company. VLAN 30 gave it separation from employees and servers – but that alone is not enough. You want one more thing: <b>guests should not see each other either</b>. Why? So that two strangers on the same visitor Wi-Fi cannot poke into each other’s laptops – if one is infected, it will not infect the other. This is called <b>client isolation</b> and is the standard choice for guest Wi-Fi (you met it in the course <i>Switching and VLANs</i> and it returns in the Wireless in practice course). Sum up the guest logic in one sentence: <b>separate them from the company (VLAN) and from each other (client isolation), and let them out only outward.</b> This, by the way, illustrates the principle that drives all network security: <b>the less you trust someone, the less you allow them.</b> A guest is at the very bottom of the trust spectrum – so it gets the absolute minimum. Servers, which you trust most, you will conversely protect most carefully. And that protection of servers is exactly what the firewall is about, after addresses.',
  [['client isolation','devices on the same guest network can’t see each other – one infected guest can’t infect another.'],['least trust needed','the less you trust someone, the less you allow; a guest gets the absolute minimum (out only).']]);}
function mountC15GuestVlan(){c15Mount('rnf',[
  {glow:c15g('guest','--amber'),dyn:c15lbl(440,116,'guest = a completely foreign device','--amber'),cap:'A guest laptop is a <b>foreign device</b> to the company – you don’t know who manages it or whether it is infected.'},
  {glow:c15g('guest','--green')+c15g('rtr','--green')+c15g('fw','--green')+c15g('net','--green'),dyn:c15pkt('M 440 164 L 300 108 L 178 108 L 66 108','--green')+c15lbl(180,211,'a guest may go only out to the internet','--green'),cap:'VLAN 30 separated the guest from the company. It may go <b>out only</b> to the internet – nowhere into employees or servers.'},
  {glow:c15g('guest','--red'),dyn:c15lbl(440,116,'client isolation: guests can’t see each other','--red'),cap:'Plus <b>client isolation</b>: two guests on the same Wi-Fi can’t see each other. An infected guest can’t infect the next one.'},
  {glow:c15g('guest','--cyan')+c15g('emp','--cyan')+c15g('web','--cyan')+c15g('files','--cyan'),dyn:c15lbl(430,108,'less trust → allow less','--cyan'),cap:'The principle of all security: <b>the less you trust, the less you allow</b>. Guest at the bottom (minimum), servers at the top (best protection).'}
]);}

/* ============ L3 — Router and addresses ============ */
/* ---------- L3M1 — Give each VLAN a subnet and a gateway ---------- */
function renderC15Subnets(){return c15P('rng',
  'VLANs raised the walls – now you give each room an <b>address</b>. Recall the course <i>Routing and IP addresses</i>: devices talk via <b>IP addresses</b> and every separate network needs its own <b>subnet</b> (range of addresses). So you give each VLAN one subnet: <b>VLAN 10 employees → 10.0.10.0/24</b>, <b>VLAN 20 servers → 10.0.20.0/24</b>, <b>VLAN 30 guests → 10.0.30.0/24</b>. The ‘/24’ means the last number (0–255) distinguishes individual devices inside – in practice .1 to .254, because .0 is the network’s own address and .255 is broadcast. Still plenty of room for the whole group. Each subnet also gets a <b>gateway</b> (default gateway): the address a device sends everything that heads <b>outside its subnet</b>. By convention the gateway gets the first address, say <b>10.0.10.1</b> for employees. Who is that gateway? The <b>router</b> – a device standing with one foot in each subnet, translating traffic between them (exactly the role from the courses <i>Switching and VLANs</i> and <i>Routing and IP addresses</i>). An employee computer gets an address like 10.0.10.42, a /24 mask and gateway 10.0.10.1 – usually automatically via DHCP, so you do not set it by hand on every machine. (That DHCP server need not be a separate box, by the way – it can run right on the router.) When the DHCP server sits in just one network, a DHCP relay on the gateway forwards requests from the other subnets; you can try both in the simulator’s advanced mode. Three subnets, three gateways, one router in the middle. How the router physically hangs off all three VLANs over a single <b>trunk cable</b> you tried in the Switching and VLANs course (router-on-a-stick) – here you just build on it. The addressing plan is done; in the next module we set it in motion so the VLANs can finally (in a controlled way) talk through that router.',
  [['subnet','a range of IP addresses for one network (e.g. 10.0.10.0/24); each VLAN has its own.'],['gateway','the address a device sends everything outside its subnet to; usually .1, belongs to the router.'],['DHCP','automatically hands a device its address, mask and gateway – you don’t set them by hand.']]);}
function mountC15Subnets(){c15Mount('rng',[
  {glow:c15g('emp','--blue'),dyn:c15lbl(300,78,'10.0.10.1','--blue')+c15lbl(440,118,'VLAN 10 → 10.0.10.0/24, gateway .1','--blue'),cap:'Employees get subnet <b>10.0.10.0/24</b> and gateway 10.0.10.1. The last number distinguishes individual computers.'},
  {glow:c15g('web','--green')+c15g('files','--green'),dyn:c15lbl(300,78,'10.0.10.1','--blue')+c15lbl(300,62,'10.0.20.1','--green')+c15lbl(560,116,'VLAN 20 → 10.0.20.0/24, gateway .1','--green'),cap:'Servers get <b>10.0.20.0/24</b> with gateway 10.0.20.1. Their own subnet for the web and file server.'},
  {glow:c15g('guest','--amber'),dyn:c15lbl(300,78,'10.0.10.1','--blue')+c15lbl(300,62,'10.0.20.1','--green')+c15lbl(300,46,'10.0.30.1','--amber')+c15lbl(440,116,'VLAN 30 → 10.0.30.0/24, gateway .1','--amber'),cap:'Guests get <b>10.0.30.0/24</b>. Their address, mask and gateway are handed out by <b>DHCP</b> automatically on joining.'},
  {glow:c15g('rtr','--cyan')+c15g('emp','--cyan')+c15g('web','--cyan')+c15g('guest','--cyan'),dyn:c15lbl(300,78,'10.0.10.1','--blue')+c15lbl(300,62,'10.0.20.1','--green')+c15lbl(300,46,'10.0.30.1','--amber')+c15pkt('M 426 54 L 314 102','--cyan','1.2s')+c15pkt('M 426 158 L 314 114','--cyan','1.2s')+c15lbl(300,211,'the router = a gateway standing in each subnet','--cyan'),cap:'That gateway is the <b>router</b>: one foot in each subnet. Three subnets, three gateways, one router in the middle.'}
]);}
/* ---------- L3M4 (position 2) — DHCP in a larger network ---------- */
function renderC15Dhcp(){
  return c15P('rnq',
  'You have the subnets and gateways thought out – but who <b>hands</b> those addresses to the clients? You will not set them by hand: that is what <b>DHCP</b> is for (you know it from the course <i>Why networks exist and how data travels</i>). In a bigger network, though, three things come with it that you never meet at home. <b>1) The DHCP server need not stand in every network.</b> A newcomer’s DHCP request is a broadcast – and a broadcast does not cross a router. (How exactly a router forwards packets between networks is covered in the very next module – for now it is enough that it finds the way.) Yet you need not build a server into every VLAN: <b>one central one</b> is enough (on a server, a router, a firewall or an L3 switch), plus a <b>DHCP relay</b> on each remote network’s gateway – the gateway catches the broadcast and <b>forwards it to the server as an ordinary packet</b>, then delivers the answer back. The central server then keeps a <b>separate range (scope) for each network</b>: employees get addresses from 10.0.10.x, guests from 10.0.30.x. In the simulator (<b>advanced mode</b>): you find the ranges on a <b>router, firewall or L3 switch</b> on the <b>DHCP</b> tab, in the <b>“DHCP ranges – which networks to serve”</b> field, a network picks the server in its settings (<b>“Network DHCP server”</b>) and you add the gateway in the <b>“DHCP relay (gateway)”</b> field. <b>2) Reservations by MAC.</b> A printer or a server must not get a different address every week – you write a <b>reservation</b> into the range: “always give this MAC address this IP”. The comfort of DHCP with the permanence of a static address – and the range will not hand that address to anyone else. <b>3) DHCP can also be drained.</b> The server has a finite number of addresses – and an attacker abuses that: a <b>DHCP starvation</b> attack spews requests with made-up MAC addresses until it sucks the range dry. A new honest client then <b>gets no address at all</b> – the network “is down” for them even though everything runs. Note the kinship with rogue DHCP from The switch in depth course: there the attacker answers instead of the server, here it <b>silences</b> the server. The defense is the same as for most L2 mischief: <b>port security</b> on the access port – a port locked to one MAC simply will not pass thousands of made-up addresses. Try it right away in the task below.',
  [['DHCP relay','the gateway catches the DHCP broadcast and forwards it to a central server in another network as an ordinary packet.'],['a reservation by MAC','“always give this MAC this IP” – DHCP comfort with static-address permanence (printers, servers).'],['DHCP starvation','the attacker drains the whole range with made-up MACs – new clients get no IP; the defense is port security.'],['port security','a switch port locked to one allowed MAC address – it drops frames from made-up addresses (more in The switch in depth course).']])
  +courseCTA('rnqTask','Try the attack and the defense – open the task “DHCP starvation – the new PC gets no IP”.','Open the task');}
function mountC15Dhcp(){
  c15Mount('rnq',[
  {glow:c15g('emp','--amber'),dyn:c15lbl(440,118,'a new PC: “who gives me an address?” (broadcast)','--amber'),cap:'A new PC in the employee VLAN broadcasts for an address. But <b>no DHCP server stands in this network</b> – and a broadcast does not cross a router.'},
  {glow:c15g('emp','--cyan')+c15g('rtr','--cyan')+c15g('web','--cyan'),dyn:c15pkt('M 440 48 L 300 108 L 560 68','--cyan')+c15lbl(180,211,'DHCP relay: the gateway forwards it to the central server','--cyan'),cap:'<b>DHCP relay</b>: the gateway catches the broadcast and forwards it to the <b>central server</b> as an ordinary packet. One server thus serves all the VLANs – with its own <b>range (scope)</b> for each.'},
  {glow:c15g('files','--green'),dyn:c15lbl(560,196,'reservation: always the same IP for this MAC','--green'),cap:'<b>A reservation by MAC</b>: the printer or file server gets <b>the same address every time</b> from DHCP – and the range will not hand it to anyone else.'},
  {glow:c15g('guest','--red')+c15g('rtr','--red'),dyn:c15pkt('M 440 164 L 300 108','--red','0.8s')+c15lbl(440,211,'starvation: made-up MACs drain the range ⚠','--red'),cap:'<b>DHCP starvation</b>: the attacker spews requests with made-up MACs until the range runs dry – new clients get no IP. The defense: <b>port security</b> on their port.'}
  ]);
  var b=$('rnqTask');if(b)b.onclick=function(){courseTry('dhcp-starvation');};
}
/* ---------- L3M2 — Traffic between VLANs via the router ---------- */
function renderC15InterVlan(){return c15P('rnh',
  'Now we solve the ‘problem’ that arose in lesson 2: VLANs separated groups so perfectly that even those that should cannot talk. An employee (VLAN 10) needs the file server (VLAN 20) – but those are two different subnets with a wall between them. You know the solution from the course <i>Switching and VLANs</i> as <b>inter-VLAN routing</b>: the only one allowed through the wall is the <b>router</b> – and that is good, because it is precisely the <b>place where traffic can be controlled</b>. How it works step by step: the employee’s computer finds the target (10.0.20.5) is not in its subnet, so it sends the packet to its <b>gateway</b> (10.0.10.1 = the router). The router looks in its table, sees the target belongs to VLAN 20 and <b>forwards</b> the packet out its other foot. The reply returns the same way. Result: employees reach the files, but they <b>must pass through the router</b> – giving you one place to later allow only what you want. And a key detail: <b>the router connects only what YOU tell it to</b>. Guests (VLAN 30) also reach the gateway through it – but they head solely to the internet; into the company the router simply does not let them. Here the control is born that the firewall will tighten in lesson 4. VLANs make walls, the router makes doors. Try inter-VLAN routing in the simulator.',
  [['inter-VLAN routing','the router connects separated VLANs – the single controlled path across the wall between subnets.'],['forwarding','the router receives a packet on one foot and, by its table, sends it out the other to the target subnet.']]);}
function mountC15InterVlan(){c15Mount('rnh',[
  {glow:c15g('emp','--amber')+c15g('files','--amber'),dyn:c15lbl(430,108,'an employee needs the file server','--amber'),cap:'An employee (VLAN 10) wants the file server (VLAN 20). Two subnets, the wall from lesson 2 between them.'},
  {glow:c15g('emp','--blue')+c15g('rtr','--blue'),dyn:c15pkt('M 440 48 L 300 108','--blue')+c15lbl(300,211,'target elsewhere → send to the gateway (router)','--blue'),cap:'The computer finds the target isn’t in its subnet and sends the packet to <b>gateway</b> 10.0.10.1 – the router.'},
  {glow:c15g('rtr','--green')+c15g('files','--green'),dyn:c15pkt('M 300 108 L 560 148','--green')+c15lbl(300,211,'the router forwards into VLAN 20 ✓','--green'),cap:'The router sees the target is in VLAN 20 and <b>forwards</b> the packet. The employee reaches the files – through the router.'},
  {glow:c15g('guest','--red')+c15g('rtr','--red'),dyn:c15lbl(300,211,'the router won’t let guests into the company – out only','--red'),cap:'Key: the router connects <b>only what you tell it</b>. It sends guests to the internet, not into the company. Here control for the firewall is born.'}
]);}
/* ---------- L3M3 — NAT out to the internet ---------- */
function renderC15Nat(){return c15P('rni',
  'One last addressing piece remains: letting the company <b>out to the internet</b>. Here you hit a fact from the course <i>Routing and IP addresses</i>: your internal addresses (10.0.10.x, 10.0.20.x…) are <b>private</b> – valid only inside the company; on the public internet no one knows or routes them. Out you can go only via a <b>public</b> IP address, of which the company usually has just <b>one</b> from the provider. How can a hundred computers share one public address? The solution is <b>NAT</b> (network address translation), more precisely its variant <b>PAT</b>: on the way out the router <b>rewrites</b> the internal address to that one public one (and remembers by port numbers which reply belongs to whom). To the internet it looks like all the company’s traffic comes from a single address; when a reply returns, the router translates it by port back to the right internal computer. NAT has a pleasant security side effect too: from outside there is <b>nowhere to ‘knock’</b> – internal computers have no public address, so an attacker on the internet does not see them directly (but it is no substitute for a firewall, just a side effect!). In the simulator you enable NAT on the router (outbound PAT on the public interface) and immediately see the private addresses ‘hide’ behind one public one. That completes the addressing layer: inside, three subnets joined by the router; outward, one public address via NAT. You have a working network – now let us protect it.',
  [['NAT / PAT','the router rewrites internal private addresses to one public one; by ports it returns replies.'],['private vs public IP','private (10.0.x.x) is valid only inside; out you go via one public address from the provider.']]);}
function mountC15Nat(){c15Mount('rni',[
  {glow:c15g('emp','--amber')+c15g('web','--amber')+c15g('guest','--amber'),dyn:c15lbl(430,108,'internal 10.0.x.x addresses are private','--amber'),cap:'Internal addresses (10.0.10.x, 10.0.20.x…) are <b>private</b> – on the public internet no one knows or routes them.'},
  {glow:c15g('emp','--blue')+c15g('rtr','--blue'),dyn:c15pkt('M 440 48 L 300 108','--blue')+c15lbl(300,211,'the router rewrites the source to one public IP','--blue'),cap:'The company usually has <b>one</b> public address from the provider. On the way out the router rewrites the internal address to it – that is <b>NAT/PAT</b>.'},
  {glow:c15g('rtr','--green')+c15g('fw','--green')+c15g('net','--green'),dyn:c15pkt('M 300 108 L 178 108 L 66 108','--green')+c15lbl(180,211,'out: everything from one public address ✓','--green'),cap:'To the internet all company traffic seems to come from one address. By ports the router returns each reply to the right computer.'},
  {glow:c15g('net','--red')+c15g('emp','--red')+c15g('guest','--red'),dyn:c15lbl(300,211,'from outside there’s nowhere to knock (side effect, not a firewall)','--red'),cap:'NAT side effect: internal computers have no public address, an outside attacker can’t see them directly. <b>No substitute for a firewall</b> – we add that now.'}
]);}

/* ============ L4 — Firewall and zones ============ */
/* ---------- L4M1 — Insert the firewall: inside/DMZ/outside zones ---------- */
function renderC15Zones(){return c15P('rnj',
  'The network works – now we make it <b>secure</b>. Into the path between the company and the internet you insert a <b>firewall</b> (the course <i>Network security</i>): a gatekeeper that decides pass / drop on every packet by rules. So the rules can be written sensibly, the firewall divides the world into <b>trust zones</b>. You know the three classic ones: <b>outside</b> (the internet – trust no one from here), <b>inside</b> (the internal company network – employees, trusted) and <b>DMZ</b> (the demilitarized zone – the place for servers that people look at from outside). Why a special zone for servers? Because a web server <b>must</b> be reachable from the internet, making it the most exposed to attack. If it sat in inside and someone hacked it, the attacker would have a foot straight in the company. So you put it in the <b>DMZ</b>: if it falls, the attacker is stuck in a separate zone and cannot reach inside (and the file server with sensitive data) through the firewall. Note that a <b>VLAN and a zone are not the same</b>: a VLAN is a boundary on the switch (L2), a zone is a firewall concept (by trust) – you just map them to each other by hand now. So map your VLANs to zones: employees = inside, <b>web server = DMZ</b>, guests = their own untrusted zone close to outside. The file server with internal data belongs to inside (or its own strict zone), because it has no business going out. Zones are just <b>boxes by trust</b>; only the rules between them (the next two modules) decide who may go where.',
  [['trust zones','inside (company), outside (internet), DMZ (exposed servers); the firewall writes rules by them.'],['DMZ','a separate zone for internet-facing servers; if they fall, the attacker can’t reach inside.']]);}
function mountC15Zones(){c15Mount('rnj',[
  {glow:c15g('fw','--red')+c15g('net','--red'),dyn:c15lbl(120,211,'firewall = gatekeeper between company and internet','--red'),cap:'Into the path between company and internet you insert a <b>firewall</b>: on each packet it decides pass or drop.'},
  {glow:c15g('emp','--blue')+c15g('files','--blue'),dyn:c15lbl(430,108,'inside: employees and internal files (trust)','--blue'),cap:'The <b>inside</b> zone: the internal network – employees and the file server with internal data. Most trusted.'},
  {glow:c15g('web','--amber'),dyn:c15lbl(560,116,'DMZ: the web is exposed, so kept apart','--amber'),cap:'The <b>DMZ</b> zone: the web server must be reachable from the internet and is thus most exposed. If it falls, the attacker is stuck here.'},
  {glow:c15g('guest','--violet')+c15g('net','--violet'),dyn:c15lbl(300,211,'guests = untrusted zone close to outside','--violet'),cap:'Guests get their own <b>untrusted</b> zone close to outside. Zones are boxes by trust – rules come next.'}
]);}
/* ---------- L4M2 — Servers into the DMZ (web out on 443) ---------- */
function renderC15Dmz(){return c15P('rnk',
  'Now we write rules for the most valuable and most exposed device – the <b>web server in the DMZ</b>. You want the web to <b>work for internet visitors</b> without throwing the company wide open. The key is to let in <b>only and exactly what is necessary</b>. A web page runs on <b>port 443</b> (HTTPS, the course <i>Why networks exist and how data travels</i>). So you write a rule: ‘from outside to the DMZ web server, port 443 → allow’. Period. No other door leads into the server from outside: whoever tries SSH (22), the database or anything else hits a wall. This is called the <b>minimal attack surface</b> – the fewer open ports, the fewer places someone can attack you. And now the second, easily forgotten half: <b>the DMZ must not itself initiate a connection into inside</b>. Why? Because if an attacker did take over the web, they must not hop onward to the file server. So you allow no ‘from DMZ to inside’ rule (at most a narrow exception if the web genuinely needs, say, a database – and even that only to a specific port and server). Result: from outside anyone reaches the web on 443, but the web itself is in a cage – it cannot look out into the company. This is exactly the point of a DMZ in practice. Try publishing the web into the DMZ in the simulator and verify 443 passes and the rest does not.',
  [['publishing on 443','a single rule from outside to the DMZ on port 443 (HTTPS) exposes the web, nothing more.'],['minimal attack surface','open only necessary ports; the fewer doors, the fewer places to attack.'],['DMZ initiates nothing into inside','the DMZ may not open a connection into the company – a hijacked web must not hop to the files.']]);}
function mountC15Dmz(){c15Mount('rnk',[
  {glow:c15g('net','--green')+c15g('fw','--green')+c15g('rtr','--green')+c15g('web','--green'),dyn:c15pkt('M 66 108 L 178 108 L 300 108 L 560 68','--green')+c15lbl(180,211,'from outside to the web: port 443 → allow ✓','--green'),cap:'A single rule: <b>from the internet to the web server, port 443</b> (HTTPS) → allow. The web works for visitors.'},
  {glow:c15g('net','--red')+c15g('web','--red'),dyn:c15lbl(300,211,'other ports (SSH 22, DB…) → drop ⚠','--red'),cap:'Everything else from outside (SSH, the database…) the firewall <b>drops</b>. This is the <b>minimal attack surface</b>.'},
  {glow:c15g('web','--red')+c15g('files','--red'),dyn:c15lbl(430,108,'no connection initiated from DMZ into inside ⚠','--red'),cap:'The other half: <b>the DMZ must not initiate a connection into inside</b>. A hijacked web thus can’t hop to the file server.'},
  {glow:c15g('net','--green')+c15g('web','--green')+c15g('files','--cyan'),dyn:c15lbl(300,211,'web caged: reachable outside, but no reach into the company','--cyan'),cap:'Result: anyone reaches the web on 443, but it is caged – it can’t see into the company. That is the point of a DMZ.'}
]);}
/* ---------- L4M3 — Guests out only, default-deny ---------- */
function renderC15Rules(){return c15P('rnl',
  'It remains to finish the rules for the other zones and, above all, to snap shut the single most important rule of all. First the <b>guests</b>: per the plan they may reach <b>only the internet</b>. So you write ‘from the guest zone to outside → allow’ and nothing else; ‘from guest to inside’ or ‘from guest to DMZ’ simply do not exist, so guests cannot reach the company. <b>Employees</b> (inside) may go out to the internet and to the file server – so you allow ‘inside → outside’ and ‘inside → file server on the relevant port’. And now the main thing: what happens to a packet that <b>matches no allow rule</b>? <b>Default-deny</b> must hold: <b>whatever is not explicitly allowed is forbidden</b>. This is the heart of the whole firewall philosophy from the course <i>Network security</i>. Without it you would write forever – enumerating everything you want to forbid is endless and one day you forget something. With default-deny the logic is inverted and safe: you allow a narrow list of the necessary and <b>everything else drops by itself</b>. Order matters (the course <i>Network security</i>, first-match): specific allows on top, default-deny as the last rule at the bottom. Now you have the complete set: web out on 443, employees to files and out, guests out only, and behind it all the closed door of default-deny. The network is built and protected. In the last lesson we <b>test and harden</b> it.',
  [['default-deny','whatever is not explicitly allowed is forbidden; the last rule at the bottom, the heart of the firewall.'],['guests out only','allow guest → outside and nothing more; no rule into inside or DMZ exists.'],['rule order','first-match: specific allows on top, default-deny last (the course <i>Network security</i>).']]);}
function mountC15Rules(){c15Mount('rnl',[
  {glow:c15g('guest','--green')+c15g('rtr','--green')+c15g('fw','--green')+c15g('net','--green'),dyn:c15pkt('M 440 164 L 300 108 L 178 108 L 66 108','--green')+c15lbl(180,211,'guest → outside: allow; nowhere else','--green'),cap:'<b>Guests</b>: rule ‘guest → internet → allow’ and nothing more. No rule leads into inside or DMZ.'},
  {glow:c15g('emp','--blue')+c15g('files','--blue')+c15g('net','--blue'),dyn:c15lbl(430,108,'inside → files + out: allow','--blue'),cap:'<b>Employees</b>: you allow ‘inside → file server’ and ‘inside → internet’. A narrow list of what they truly need.'},
  {glow:c15g('fw','--red')+c15g('guest','--red')+c15g('files','--red')+c15g('emp','--red'),dyn:c15lbl(300,211,'what isn’t allowed is forbidden = default-deny','--red'),cap:'The firewall’s heart: <b>default-deny</b>. Whatever matches no allow rule, the firewall drops. The last rule at the bottom.'},
  {glow:c15g('net','--cyan')+c15g('fw','--cyan')+c15g('web','--cyan')+c15g('emp','--cyan')+c15g('files','--cyan')+c15g('guest','--cyan'),dyn:c15lbl(300,211,'complete rule set → network built and protected ✓','--cyan'),cap:'You have the complete set: web on 443, employees to files and out, guests out only, default-deny over all. Testing remains.'}
]);}

/* ============ L5 — Test and harden ============ */
/* ---------- L5M1 — Passage test: what is allowed and what is not ---------- */
function renderC15Test(){return c15P('rnm',
  'Building the network is half the work; the other half is to <b>prove it does exactly what it should</b> – and nothing more. On a finished topology never rely on the impression ‘looks fine’. Open the <b>path test</b> in the simulator (send a test packet from point A to point B) and go through your lesson-1 plan <b>point by point</b> – both what SHOULD pass and what MUST NOT. Verify the positive cases: an employee reaches the file server (inside → files ✓), employee and guest reach the internet (→ outside ✓), an internet visitor opens the web on 443 (outside → DMZ:443 ✓). And above all verify the <b>negative</b> cases, because they reveal holes: a guest <b>must not</b> reach the file server (guest → inside = dropped), a visitor from the internet must not reach the file server (outside → inside = dropped) nor the web on any port other than 443. When a test comes out other than you expect, you have a <b>bug in the rules</b> – and it is better to find it now in the simulator than in production. This habit of ‘<b>test both: what should pass and what must not</b>’ marks a good network engineer. Go through the whole list and make sure your company does exactly what you planned.',
  [['path test','you send a test packet from A to B and check whether it passes or the rules drop it.'],['test both','verify not only what SHOULD pass but especially what MUST NOT – negative tests reveal holes.']]);}
function mountC15Test(){c15Mount('rnm',[
  {glow:c15g('emp','--green')+c15g('rtr','--green')+c15g('files','--green'),dyn:c15pkt('M 440 48 L 300 108 L 560 148','--green')+c15lbl(300,211,'positive test: employee → files ✓','--green'),cap:'Verify what <b>should</b> pass: an employee reaches the file server. Inside → files works – correct.'},
  {glow:c15g('net','--green')+c15g('fw','--green')+c15g('rtr','--green')+c15g('web','--green'),dyn:c15pkt('M 66 108 L 178 108 L 300 108 L 560 68','--green')+c15lbl(180,211,'positive test: internet → web on 443 ✓','--green'),cap:'An internet visitor opens the web on port 443. Outside → DMZ:443 passes – exactly as intended.'},
  {glow:c15g('guest','--red')+c15g('files','--red'),dyn:c15lbl(300,211,'negative test: guest → files = dropped ✓','--red'),cap:'Now the important part – <b>negative</b> tests: a guest <b>must not</b> reach the file server. Guest → inside = dropped. Good.'},
  {glow:c15g('net','--red')+c15g('files','--red'),dyn:c15lbl(300,211,'negative test: internet → files = dropped ✓','--red'),cap:'And an internet visitor must not reach the file server. Outside → inside = dropped. Testing both = a good engineer’s habit.'}
]);}
/* ---------- L5M2 — Topology check and blast radius ---------- */
function renderC15Audit(){return c15P('rnn',
  'With the path test you verified <b>individual paths</b>. Now lift your view and look at the network <b>as a whole</b> – that is what the <b>topology check</b> in the simulator is for: it walks your network and flags weak spots easily missed in per-path tests. What does it typically find? A <b>forgotten over-broad rule</b> (say ‘inside → anywhere’ instead of a narrow list), a <b>service needlessly exposed outward</b>, a <b>device without segmentation</b>, or a path you did not intend. For each finding ask the lesson-1 question: <b>what is the blast radius?</b> If this device fell or this rule were abused, <b>how far would the damage spread?</b> This is how you tell whether your segmentation truly works: an infected guest should be able to take down at most itself and a few other guests – not the whole company. A hacked web in the DMZ should be stuck in the DMZ – not hop to the file server. In the simulator there is a <b>Blast-radius</b> button for exactly this: it computes where an attacker from a chosen source can reach, so you do not have to just imagine it. When the audit shows one hijacked device reaches further than you want, you <b>have a candidate for hardening</b>: add a rule, narrow an allow, split off another segment. Network security is not one-off – it is a <b>loop</b>: build, test paths, run the audit, shrink the blast radius, and after every change (a new server, a new app) repeat it. Your first company network now stands on solid ground.',
  [['topology check','a tool that walks the network as a whole and flags weak spots and over-broad rules.'],['shrink the blast radius','for each finding ask how far damage spreads, and harden until it reaches no further than you want.']]);}
function mountC15Audit(){c15Mount('rnn',[
  {glow:c15g('net','--cyan')+c15g('fw','--cyan')+c15g('rtr','--cyan')+c15g('emp','--cyan')+c15g('web','--cyan')+c15g('files','--cyan')+c15g('guest','--cyan'),dyn:c15lbl(300,211,'the audit walks the network as a whole','--cyan'),cap:'The <b>topology check</b> lifts your view above single tests: it walks the network as a whole and flags weak spots.'},
  {glow:c15g('web','--amber')+c15g('net','--amber'),dyn:c15lbl(300,211,'finding: a service needlessly exposed ⚠','--amber'),cap:'A typical finding: an over-broad rule or a service needlessly exposed. For each, ask the blast-radius question.'},
  {glow:c15g('guest','--green')+c15g('web','--green')+c15g('files','--green'),dyn:c15lbl(430,211,'an infected guest downs at most itself – not the company ✓','--green'),cap:'Good segmentation: an infected guest downs a few guests at most, a hijacked web is stuck in the DMZ. The blast radius is small.'},
  {glow:c15g('emp','--blue')+c15g('web','--blue')+c15g('files','--blue')+c15g('guest','--blue'),dyn:c15lbl(300,211,'loop: build → test → audit → harden','--blue'),cap:'Security is a <b>loop</b>: build, test paths, run the audit, shrink the blast radius – and repeat after every change.'}
]);}
/* ---------- L5M3 — Summary and what next ---------- */
function renderC15Summary(){return c15P('rno',
  'You did it: from a few sentences of requirements stands a finished <b>working and secure company network</b>. Retrace the path you walked. <b>Requirements and plan</b>: three groups by trust level (employees, servers, guests), the goal of shrinking the blast radius, the plan on paper before the cables. <b>Segmentation</b>: three <b>VLANs</b> raised invisible walls, with guests also isolated from each other. <b>Addresses</b>: each VLAN got a <b>subnet and gateway</b>, the <b>router</b> joined them in a controlled way (inter-VLAN) and <b>NAT</b> let the company out via one public address. <b>Firewall</b>: inside/DMZ/outside zones, the web published on 443, guests out only, and over it all <b>default-deny</b>. <b>Test and audit</b>: you verified what should pass and what must not, and shrank the blast radius by audit. Notice you used almost nothing new – you just <b>assembled the courses from <i>Why networks exist and how data travels</i> to <i>Network security</i> into one meaningful whole</b>. And that is the network engineer’s main skill: not to know ever more terms, but to <b>compose the known ones into a network that works and holds</b>. What next? This network still has <b>one of everything</b> – one router, one firewall, one link out. What happens when one of them fails? The next course in the track picks up exactly there: <b>Redundancy and Spanning Tree</b> – how to build a network that survives when something breaks. You have a great foundation. Go build on.',
  [['compose what you know','the main skill: assemble the courses from <i>Why networks exist and how data travels</i> to <i>Network security</i> into a network that works and holds – not to hoard terms.'],['what next → redundancy','the network has one of everything so far; the next course covers surviving a failure (Spanning Tree).']]);}
function mountC15Summary(){c15Mount('rno',[
  {glow:c15g('emp','--blue')+c15g('web','--green')+c15g('files','--green')+c15g('guest','--amber'),dyn:c15lbl(430,108,'plan and segmentation: three groups, three VLANs','--blue'),cap:'<b>Plan and segmentation</b>: three groups by trust, three VLANs as invisible walls, guests isolated even from each other.'},
  {glow:c15g('emp','--cyan')+c15g('rtr','--cyan')+c15g('files','--cyan')+c15g('net','--cyan'),dyn:c15pkt('M 440 48 L 300 108 L 560 148','--cyan')+c15lbl(300,211,'addresses: subnets, router (inter-VLAN) and NAT out','--cyan'),cap:'<b>Addresses</b>: each VLAN got a subnet and gateway, the router joined them in a controlled way, NAT let the company out.'},
  {glow:c15g('net','--red')+c15g('fw','--red')+c15g('rtr','--red')+c15g('web','--red'),dyn:c15pkt('M 66 108 L 178 108 L 300 108 L 560 68','--red')+c15lbl(180,211,'firewall: zones, web on 443, default-deny','--red'),cap:'<b>Firewall</b>: inside/DMZ/outside zones, web published on 443, guests out only, default-deny over all. Then test and audit.'},
  {glow:c15g('net','--green')+c15g('fw','--green')+c15g('rtr','--green')+c15g('emp','--green')+c15g('web','--green')+c15g('files','--green')+c15g('guest','--green'),dyn:c15lbl(300,211,'done! what next → Redundancy and Spanning Tree','--green'),cap:'You assembled the courses from <i>Why networks exist and how data travels</i> to <i>Network security</i> into a working, secure network. What next? It has one of everything → course <b>Redundancy and Spanning Tree</b>. Congratulations!'}
]);}

